```javascript
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // Dimensions matched to source aspect ratio 512/320 = 1.6
  const CARD_W = 2.0;
  const CARD_H = 1.25;
  const BORDER_W = CARD_W + 0.06;
  const BORDER_H = CARD_H + 0.06;

  const group = new Group();

  // --- Border / accent edge plane ---
  const borderGeo = new PlaneGeometry(BORDER_W, BORDER_H);
  const borderMat = new MeshBasicNodeMaterial({
    color: new ctx.THREE.Color(config.colors?.accent ?? '#ff2a38'),
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // --- Main image plane ---
  const imgGeo = new PlaneGeometry(CARD_W, CARD_H);
  const imgMat = new MeshBasicNodeMaterial({
    color: new ctx.THREE.Color(config.colors?.surface ?? '#0b0b10'),
  });
  const imgMesh = new Mesh(imgGeo, imgMat);
  group.add(imgMesh);

  // --- Load texture ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // --- GSAP timelines ---
  const tlHover = gsap.timeline({ paused: true });
  tlHover
    .to(imgMesh.position, { y: 0.15, duration: 0.3, ease: 'power2.out' }, 0)
    .to(borderMat, { opacity: 1, duration: 0.3, ease: 'power2.out' }, 0);

  const tlPress = gsap.timeline({ paused: true });
  tlPress
    .to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
    .to(group.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' });

  // --- Handlers ---
  group.userData.handlers = {
    hover: {
      enter: () => {
        tlHover.play();
      },
      leave: () => {
        tlHover.reverse();
      },
    },
    click: {
      press: () => {
        tlPress.restart();
      },
      tap: () => {
        ctx.emit('hub-journal.select', {});
      },
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tlHover.kill();
    tlPress.kill();
    imgMat.dispose();
    imgGeo.dispose();
    borderMat.dispose();
    borderGeo.dispose();
  };

  return group;
}
